#!/usr/bin/env python3
"""Pack the authored VA/FM percussion without altering the115 library masters."""
import argparse,hashlib,importlib.util,json,struct,zlib,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
spec=importlib.util.spec_from_file_location('factory_pack',ROOT/'tools/content/factory_library_pack.py');packing=importlib.util.module_from_spec(spec);spec.loader.exec_module(packing)
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--write',action='store_true');a=p.parse_args();source=ROOT/'assets/factory-synth-drums';files=[];blob=bytearray();maximum=0
 previous=json.loads((source/'manifest.json').read_text());pending=previous.get('pending_containers',[]);version=int(re.search(r'kFormatVersion\s*=\s*(\d+)',(ROOT/'src/project_format_version.h').read_text())[1])
 for path in sorted(source.rglob('*')):
  if path.suffix not in ('.mgxp','.mgxk','.wav'):continue
  data=path.read_bytes();rel=path.relative_to(source);kind=rel.parts[0];dest={'PRESETS':'FACTORY/PRESETS/DRUMS','KITS':'FACTORY/KITS','DRUMS':'FACTORY/DRUMS/VA-FM'}[kind]+'/'+path.name
  if path.suffix!='.wav':assert data[:6]==b'MGXC'+struct.pack('<H',version) and zlib.crc32(data[4:-4])==struct.unpack('<I',data[-4:])[0]
  packed=packing.pack(data);sha=hashlib.sha256(data).hexdigest();files.append({'master':str(rel),'path':dest,'bytes':len(data),'sha256':sha,'crc32':zlib.crc32(data),'offset':len(blob),'packed':len(packed)});blob.extend(packed);maximum=max(maximum,len(data))
 assert len(files)==13-len(pending) and not ({x['master'] for x in files}&set(pending)) and sum(x['master'].startswith('DRUMS/') for x in files)==6
 text='// Generated by tools/content/factory_synth_drums_pack.py; boot-only GBL1 restore.\n'
 text+=f'inline constexpr unsigned kFactorySynthDrumMaxBytes={maximum};\ninline constexpr unsigned kFactorySynthDrumCount={len(files)};\ninline constexpr uint8_t kFactorySynthDrumPacked[]={{\n'
 for at in range(0,len(blob),24):text+=' '+','.join(str(x) for x in blob[at:at+24])+',\n'
 text+='};\ninline constexpr FactoryLibraryEntry kFactorySynthDrums[]={\n'
 for f in files:text+=' {'+json.dumps(f['path'])+f",{f['bytes']},{f['offset']},{f['packed']},"+'{'+','.join(str(x) for x in bytes.fromhex(f['sha256']))+'}},\n'
 text+='};\n';header=ROOT/'src/generated/factory_synth_drums.inc';manifest={'format':version,'pending_containers':pending,'origin':'Offline48kHz actual Engine render, seed0x53445231+i, velocity110, native root note per recipe, NoteOff10ms before end,2ms final fade, mono PCM16 normalized to peak24575. Six standalone native synth presets plus one baked sample kit; no user pool registration.','recipe_sha256':hashlib.sha256((ROOT/'src/synth_drum_recipes.h').read_bytes()).hexdigest(),'generator_sha256':hashlib.sha256((ROOT/'tools/content/synth_drums.cpp').read_bytes()).hexdigest(),'files':files}
 target=source/'manifest.json';encoded=json.dumps(manifest,indent=2)+'\n'
 if a.write:header.write_text(text);target.write_text(encoded)
 elif not header.exists() or header.read_text()!=text or not target.exists() or target.read_text()!=encoded:raise SystemExit('Synth drum assets/pack differ; regenerate the authored kit before deployment')
 print(f'Synthesis drums:{len(files)} files/{sum(f["bytes"] for f in files)} bytes -> {len(blob)} packed; scratch{maximum}; pending containers {len(pending)}; compatible baked WAV retained')
if __name__=='__main__':main()
